for j in 0..Nv:
  v = lerp(v0, v1, j/Nv)
  for i in 0..Nu:
    u = lerp(u0, u1, i/Nu)
    P[i,j] = surface(u,v)
    UV[i,j] = (i/Nu, j/Nv)
for each cell (i,j):
  emit triangles with declared winding
N = normalize(cross(derivativeU, derivativeV)) or computeNormals(mesh)
return validated mesh

profile = sampleProfile(r, y, Nu)
for i in 0..Nu:
  for k in 0..Nθ:
    θ = θ_start + sweepAngle*k/Nθ
    vertex[i,k] = (r[i]*cosθ, y[i], r[i]*sinθ)
for each adjacent profile ring and angular segment:
  connect quad with fixed winding
handleAxisEndpoints(r==0)
addCapsIfRequested()
computeNormalsUVBounds(); validate()

validateContour(C)
for j in 0..Ns:
  s = j/Ns
  for i in 0..Nu:
    P[j,i] = C(u_i) + s*d
connectAdjacentProfiles(P)
if closedContour and solid:
  triangulateCap(P[0]); triangulateCap(P[Ns])
computeNormalsUVBounds(); validateMesh()

for each face f: F[f] = average(vertices(f))
for each edge e=(v1,v2):
  if interior: E[e] = (v1+v2+F[f1]+F[f2])/4
  else: E[e] = boundaryRule(v1,v2,crease)
for each vertex v:
  Vnew[v] = vertexRule(v, adjacentFaces, adjacentEdges, valence)
newMesh = rebuildFaces(Vnew,E,F)
validateTopology(newMesh)
repeat levelCount

queue=[(identity, 0, seedRoot)]
while queue not empty and instanceCount < budget:
  (M, depth, seed) = pop(queue)
  emitInstance(P0, M, seed)
  if depth < maxDepth and projectedSize(M) > minSize:
    for i, T_i in enumerate(transforms):
      push(queue, (M*T_i, depth+1, hash(seed,i)))
return instanceSet
